                                        if isinstance(d, dict) and 'input' in d and 'output' in d:
                                            all_demos.append({
                                                'session': session_file,
                                                'line': line_num,
                                                'demo': d
                                            })
                            # Also look for 'demos' as top level key
                            elif 'demos' in entry and isinstance(entry['demos'], list):
                                demos = entry['demos']
                                for d in demos:
                                    if isinstance(d, dict) and 'input' in d and 'output' in d:
                                        all_demos.append({
                                            'session': session_file,
                                            'line': line_num,
                                            'demo': d
                                        })
